function nextDivisibleProduct(n: number, t: number): number {
  const product = (x: number): number => {
    let p = 1;
    while (x > 0) {
      p *= x % 10;
      x = Math.floor(x / 10);
    }
    return p;
  };
  let x = n;
  while (product(x) % t !== 0) x++;
  return x;
}

