class Solution:
    def nextDivisibleProduct(self, n: int, t: int) -> int:
        def product(x: int) -> int:
            p = 1
            while x > 0:
                x, d = divmod(x, 10)
                p *= d
            return p

        x = n
        while product(x) % t != 0:
            x += 1
        return x

